import { Image } from 'expo-image'

import { hasProviderIcon } from './provider-icon-svg'

export { hasProviderIcon }

/**
 * Provider marks are rendered as bitmaps.
 *
 * react-native-svg draws into a native view that swallows touches on Android,
 * which made the social sign-in buttons unclickable; a bitmap inside an
 * expo-image does not intercept the press. The Google mark is generated by
 * `scripts/render-google-mark.py`.
 */
const marks: Record<string, number> = {
  github: require('../../../assets/social/github.png'),
  google: require('../../../assets/social/google.png'),
}

export function ProviderIcon({
  color,
  provider,
  size,
}: {
  color: string
  provider: string
  size: number
}) {
  const source = marks[provider]
  if (!source) return null
  return (
    <Image
      contentFit="contain"
      source={source}
      style={{ height: size, width: size }}
      tintColor={provider === 'google' ? undefined : color}
    />
  )
}
